// UserServiceServer is the server API for UserService service.
// All implementations must embed UnimplementedUserServiceServer
// for forward compatibility.
type UserServiceServer interface {
	GetUserById(context.Context, *GetUserByIdReq) (*UserInfo, error)
	GetUserByPhone(context.Context, *GetUserByPhoneReq) (*UserInfo, error)
	CreateOrUpdateUser(context.Context, *CreateUserReq) (*UserInfo, error)
	UpdateUserCommunity(context.Context, *UpdateCommunityReq) (*common.CommonResponse, error)
	ListUsers(context.Context, *ListUsersReq) (*ListUsersResp, error)
	// BatchGetUsers 会员批量查询：后台订单列表按行取会员名，替代逐行 GetUserById 的 N 次往返
	BatchGetUsers(context.Context, *BatchGetUsersReq) (*BatchGetUsersResp, error)
	// 地址
	ListAddresses(context.Context, *ListAddressesReq) (*ListAddressesResp, error)
	GetAddress(context.Context, *GetAddressReq) (*AddressInfo, error)
	CreateAddress(context.Context, *CreateAddressReq) (*AddressInfo, error)
	UpdateAddress(context.Context, *UpdateAddressReq) (*AddressInfo, error)
	DeleteAddress(context.Context, *DeleteAddressReq) (*common.CommonResponse, error)
	SetDefaultAddress(context.Context, *SetDefaultAddressReq) (*common.CommonResponse, error)
	// 社区
	ListCommunities(context.Context, *ListCommunitiesReq) (*ListCommunitiesResp, error)
	GetCommunity(context.Context, *GetCommunityReq) (*CommunityInfo, error)
	ListNearbyCommunities(context.Context, *ListNearbyCommunitiesReq) (*ListCommunitiesResp, error)
	CreateCommunity(context.Context, *CreateCommunityReq) (*CommunityInfo, error)
	UpdateCommunity(context.Context, *UpdateCommunityInfoReq) (*CommunityInfo, error)
	DeleteCommunity(context.Context, *DeleteCommunityReq) (*common.CommonResponse, error)
	// 用户资料
	UpdateUserProfile(context.Context, *UpdateUserProfileReq) (*UserInfo, error)
	// UpdateMember 后台编辑会员基础资料（昵称/性别/生日，社区语境校验）
	UpdateMember(context.Context, *UpdateMemberReq) (*UserInfo, error)
	// 行政区划
	ListRegionChildren(context.Context, *ListRegionChildrenReq) (*ListRegionChildrenResp, error)
	ListRegions(context.Context, *ListRegionsReq) (*ListRegionsResp, error)
	MatchRegionByName(context.Context, *MatchRegionByNameReq) (*RegionMatchInfo, error)
	CreateRegionUpdateTask(context.Context, *CreateRegionUpdateTaskReq) (*RegionUpdateTaskInfo, error)
	GetRegionUpdateTask(context.Context, *GetRegionUpdateTaskReq) (*RegionUpdateTaskInfo, error)
	ApplyRegionUpdateTask(context.Context, *ApplyRegionUpdateTaskReq) (*common.CommonResponse, error)
	// 管理员
	GetAdminByUsername(context.Context, *GetAdminByUsernameReq) (*AdminInfo, error)
	// 按 ID 查询管理员（refresh 时实时校验账号状态：停用/删除即令牌失效）
	GetAdminById(context.Context, *GetAdminByIdReq) (*AdminInfo, error)
	ListAdmins(context.Context, *ListAdminsReq) (*ListAdminsResp, error)
	CreateAdmin(context.Context, *CreateAdminReq) (*AdminInfo, error)
	UpdateAdmin(context.Context, *UpdateAdminReq) (*AdminInfo, error)
	DeleteAdmin(context.Context, *DeleteAdminReq) (*common.CommonResponse, error)
	// 查询账号任职的全部社区与角色（账号管理页任职详情弹窗，超管专用）
	GetAdminAssignments(context.Context, *GetAdminAssignmentsReq) (*GetAdminAssignmentsResp, error)
	ChangeAdminPassword(context.Context, *ChangeAdminPasswordReq) (*common.CommonResponse, error)
	// GetAdminContext 实时解析管理员在指定社区的权限上下文（任职角色权限并集）
	GetAdminContext(context.Context, *GetAdminContextReq) (*AdminContextInfo, error)
	// 角色
	ListRoles(context.Context, *ListRolesReq) (*ListRolesResp, error)
	GetRole(context.Context, *GetRoleReq) (*RoleInfo, error)
	CreateRole(context.Context, *CreateRoleReq) (*RoleInfo, error)
	UpdateRole(context.Context, *UpdateRoleReq) (*RoleInfo, error)
	DeleteRole(context.Context, *DeleteRoleReq) (*common.CommonResponse, error)
	// 会员-社区关联与状态
	// MarkUserCommunity 幂等记录会员与社区的关联（收货地址/下单/后台添加会员时调用）
	MarkUserCommunity(context.Context, *MarkUserCommunityReq) (*common.CommonResponse, error)
	// SetUserStatus 设置会员状态（拉黑/恢复）
	SetUserStatus(context.Context, *SetUserStatusReq) (*common.CommonResponse, error)
	// CreateMember 注册会员（手机号幂等注册到指定社区，已注册时复用并关联）
	CreateMember(context.Context, *CreateMemberReq) (*CreateMemberResp, error)
	// --- 履约人员（B 社区履约工作台） ---
	// 履约人员 = 本社区任职且绑定了会员的员工（admin_users.user_id），配置入口在员工编辑页
	// 列出某社区全部履约人员（后台订单指派弹窗数据源）
	ListFulfillers(context.Context, *ListFulfillersReq) (*ListFulfillersResp, error)
	// 校验用户在某社区是否履约人员（C 端工作台入口判断 + gateway 鉴权）
	CheckFulfiller(context.Context, *CheckFulfillerReq) (*CheckFulfillerResp, error)
	// --- 客户端渠道管理（微信小程序/公众号/App/浏览器 H5） ---
	// 渠道主数据：各端访问凭证（AppID/AppSecret）、启用开关与排序；
	// 登录与支付链路按渠道取用凭证，支付配置按渠道勾选适用范围
	ListClientChannels(context.Context, *ListClientChannelsReq) (*ListClientChannelsResp, error)
	GetClientChannel(context.Context, *GetClientChannelReq) (*ClientChannelInfo, error)
	SaveClientChannel(context.Context, *SaveClientChannelReq) (*ClientChannelInfo, error)
	// 查询用户在指定客户端渠道的微信 openid（渠道身份表优先，mp 渠道回落 users.openid 存量口径）
	GetUserChannelOpenid(context.Context, *GetUserChannelOpenidReq) (*GetUserChannelOpenidResp, error)
	// 登录后写入/更新用户在指定渠道的微信身份（幂等 upsert）
	UpsertUserChannelIdentity(context.Context, *UpsertUserChannelIdentityReq) (*common.CommonResponse, error)
	// 站点设置：平台级品牌与部署域名（单行配置，仅超管可写）
	// base_url 是部署域名的唯一来源，网关据此派生支付回调地址、附件外链与 HTML 品牌注入
	GetSiteConfig(context.Context, *GetSiteConfigReq) (*SiteConfigInfo, error)
	SaveSiteConfig(context.Context, *SaveSiteConfigReq) (*SiteConfigInfo, error)
	mustEmbedUnimplementedUserServiceServer()
}

